/*! Open Historia — every country of a scenario rated for war by the AI, together © 2026 Nicholas Krol, AGPL-3.0-or-later (see LICENSE). */
// "remove region count power entirely, have it be generated by the ai for
// every country by the scenario designer and that then ships with the scenario
// (like how politics generation works except everything is relative to every
// other country it generates and it doesnt waste an entire tool call per
// country or whatever, it does 20 countries per api call)" (the owner,
// 2026-10-16).
//
// The Scenario Editor's Fronts section rates every country and group of a
// scenario (ScenarioMilitaryPanel.jsx): MILITARY_BATCH_MOST to a request
// (Game/AI/militaryRating.js), each request shown every polity rated before it
// as its scale; where none is, the first is shown them all and rates the
// strongest of them, so that they set the scale. What it says is written into
// the scenario's own records, which a game begins from: world.polityOverrides
// and world.groups, their `military`, and their `population` where the designer
// gave none (a country's people are what its weight in a war is counted from:
// runtime/countryWeight.js). A country the run never reached is rated in the
// game when it is first needed (Game/AI/gameplay.js ensureMilitaryFigures).
//
// Pure, and loads in plain Node: who to ask of next, and what an answer writes.

import { collectScenarioPoliticalPolities } from "../../runtime/scenarioPolities.js";
import { normalizeMilitaryStats } from "../../runtime/militaryStats.js";
import { populationFigureOf } from "../../runtime/populationFigure.js";
import { MILITARY_BATCH_MOST, ratedScaleOf, wantsRating } from "../AI/militaryRating.js";

const clean = (value) => String(value ?? "").replace(/\s+/g, " ").trim();
const fold = (value) => clean(value).toLowerCase();
const isRecord = (value) => Boolean(value) && typeof value === "object" && !Array.isArray(value);

// Every country and group of a scenario: [{ key, name, group, population, military, note }], the countries first,
// each name once.
export const scenarioMilitaryRoster = (world = {}) => {
  const overrides = isRecord(world?.polityOverrides) ? world.polityOverrides : {};
  const seen = new Set();
  const out = [];
  for (const entry of collectScenarioPoliticalPolities(world)) {
    if (entry.active === false) continue;
    const record = isRecord(overrides[entry.polityKey]) ? overrides[entry.polityKey] : {};
    const name = clean(record.name) || entry.polityKey;
    if (!name || seen.has(fold(name))) continue;
    seen.add(fold(name));
    out.push({ key: entry.polityKey, name, group: false, population: populationFigureOf(record), military: normalizeMilitaryStats(record.military), note: clean(record.note) });
  }
  for (const [key, record] of Object.entries(isRecord(world?.groups) ? world.groups : {})) {
    const name = clean(record?.name) || key;
    if (!name || seen.has(fold(name))) continue;
    seen.add(fold(name));
    out.push({ key, name, group: true, population: populationFigureOf(record), military: normalizeMilitaryStats(record?.military), note: clean(record?.description) });
  }
  return out;
};

// Whether a polity of the roster wants rating: a figure the AI rates that it lacks, or its people.
export const wantsMilitaryRating = (entry) => wantsRating(entry?.military) || !(Number(entry?.population) > 0);

// The next request of a run: { polities } (up to MILITARY_BATCH_MOST to rate) or, nobody rated yet and more to rate
// than one request takes, { pickFrom } (the strongest of them first); with `rated`, the scale, and `wanted`, the
// roster's entries asked of. null when nothing is left.
//   tried   the keys asked of already in this run: each is asked of once
//   again   every polity rated afresh, those rated before the run too: the scale is then only those rated in it
export const nextMilitaryRequest = (roster = [], { tried = new Set(), again = false } = {}) => {
  const wanted = roster.filter((entry) => !tried.has(entry.key) && (again || wantsMilitaryRating(entry)));
  if (wanted.length === 0) return null;
  const rated = ratedScaleOf(again ? roster.filter((entry) => tried.has(entry.key)) : roster, wanted.map((entry) => entry.name));
  const asking = (entries) => entries.map(({ name, note, population }) => ({ name, note, population }));
  if (rated.length === 0 && wanted.length > MILITARY_BATCH_MOST) return { pickFrom: asking(wanted), rated, wanted };
  const batch = wanted.slice(0, MILITARY_BATCH_MOST);
  return { polities: asking(batch), rated, wanted: batch };
};

// The roster's keys an answer rated, for a run's `tried`.
export const ratedKeys = (roster = [], ratings = []) => {
  const byName = new Map(roster.map((entry) => [fold(entry.name), entry.key]));
  return ratings.map((rating) => byName.get(fold(rating?.name))).filter(Boolean);
};

// What an answer writes into a scenario's world: each rated polity's figures (those it lacked; with `again`, over
// those it had) and its people where the designer gave none. { world, written }: a new world, the keys written.
export const withMilitaryRatings = (world = {}, roster = [], ratings = [], { again = false } = {}) => {
  const byName = new Map(roster.map((entry) => [fold(entry.name), entry]));
  const polities = { ...(isRecord(world?.polityOverrides) ? world.polityOverrides : {}) };
  const groups = { ...(isRecord(world?.groups) ? world.groups : {}) };
  const written = [];
  for (const rating of Array.isArray(ratings) ? ratings : []) {
    const entry = byName.get(fold(rating?.name));
    if (!entry || written.includes(entry.key)) continue;
    const store = entry.group ? groups : polities;
    const record = isRecord(store[entry.key]) ? { ...store[entry.key] } : { name: entry.name };
    const had = normalizeMilitaryStats(record.military) ?? {};
    const rated = rating.military ?? {};
    const military = normalizeMilitaryStats(again ? { ...had, ...rated } : { ...rated, ...had });
    if (military) record.military = military;
    if (!(populationFigureOf(record) > 0) && Number(rating.population) > 0) record.population = Math.round(Number(rating.population));
    store[entry.key] = record;
    written.push(entry.key);
  }
  return {
    world: { ...world, polityOverrides: polities, ...(isRecord(world?.groups) || Object.keys(groups).length > 0 ? { groups } : {}) },
    written,
  };
};
